//! Rows to test on: generated by romulus-fakedata (its plan run step by
//! step on the session, as a playground's build runs it), provided as SQL,
//! or already there.

use remus_core::Schema;
use romulus_fakedata::{Profile, Size, Step, copy_text};

use crate::{
    report::DataSource,
    session::{Rows, Session, SessionError},
    statements::Limits,
};

/// Where the rows come from.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Seed {
    /// Generated by romulus-fakedata from the base model.
    Generate(romulus_fakedata::Options),
    /// Already in the database (a playground's build, a copy of someone's
    /// playground); `label` says what they are, as a phrase the report's
    /// first step reads out ("generated rows (small, seed 7f3a91)").
    Existing { label: String },
    /// This SQL inserts them (a test's own rows).
    Sql(String),
}

/// What seeding gave.
#[derive(Debug, Clone)]
pub struct Seeded {
    pub data: DataSource,
    /// What the generator could not satisfy, in sentences.
    pub notes: Vec<String>,
}

fn size_word(size: Size) -> &'static str {
    match size {
        Size::Small => "small",
        _ => "medium",
    }
}

fn profile_word(profile: Profile) -> &'static str {
    match profile {
        Profile::Realistic => "realistic",
        _ => "edge_cases",
    }
}

/// Puts the rows in (or not, for [`Seed::Existing`]).
pub async fn seed<S: Session>(
    session: &mut S,
    base: &Schema,
    seed: &Seed,
    limits: Limits,
) -> Result<Seeded, String> {
    match seed {
        Seed::Existing { label } => Ok(Seeded {
            data: DataSource::Existing {
                label: label.clone(),
            },
            notes: Vec::new(),
        }),
        Seed::Sql(sql) => {
            session
                .run(sql, limits.read(), Rows::Skip)
                .await
                .map_err(|e| format!("the rows do not insert: {e}"))?;
            Ok(Seeded {
                data: DataSource::Provided,
                notes: Vec::new(),
            })
        }
        Seed::Generate(options) => {
            let plan = romulus_fakedata::plan(base, options).map_err(|e| e.to_string())?;
            let mut report = plan.report();
            for step in plan.steps() {
                let label = step.label();
                let failed = |e: SessionError| format!("the rows do not load ({label}): {e}");
                match step {
                    Step::Sql(sql) => {
                        session
                            .run(&sql, limits.read(), Rows::Skip)
                            .await
                            .map_err(failed)?;
                    }
                    Step::Outcome(query) => {
                        let answer = session
                            .run(&query, limits.read(), Rows::READ)
                            .await
                            .map_err(failed)?;
                        let json = answer
                            .rows
                            .first()
                            .and_then(|r| r.first().cloned().flatten())
                            .unwrap_or_default();
                        report.record_outcome(&json).map_err(|e| e.to_string())?;
                    }
                    Step::CopyTable(copy) => {
                        let statement = copy.statement();
                        let mut rows = copy.rows;
                        let mut chunks = std::iter::from_fn(move || {
                            let mut chunk = Vec::with_capacity(64 * 1024);
                            for row in rows.by_ref() {
                                copy_text(&row, &mut chunk);
                                if chunk.len() >= 64 * 1024 {
                                    break;
                                }
                            }
                            (!chunk.is_empty()).then_some(chunk)
                        });
                        session
                            .copy_in(&statement, &mut chunks, limits.read())
                            .await
                            .map_err(failed)?;
                    }
                }
            }
            Ok(Seeded {
                data: DataSource::Generated {
                    size: size_word(options.size).to_owned(),
                    profile: profile_word(options.profile).to_owned(),
                    seed: format!("{:06x}", options.seed),
                    generator: romulus_fakedata::GENERATOR_VERSION.to_string(),
                },
                notes: report.lines(),
            })
        }
    }
}
